      {sectionVisible("gallery") && <section className="portfolio-projects" id="portfolio-projects" aria-label="S&#233;lection de projets"><article><div className="portfolio-photo" role="img" aria-label="Vase sculptural et mati&#232;re artisanale" style={{ backgroundImage: "url(/media/portfolio/vase-v1.webp)" }}/><p>Objets &amp; mati&#232;res <span>&#8594;</span></p></article><article><div className="portfolio-photo" role="img" aria-label="Composition &#233;ditoriale autour d&#8217;un plat ha&#239;tien" style={{ backgroundImage: "url(/media/portfolio/food-v1.webp)" }}/><p>Saveurs d&#8217;ici <span>&#8594;</span></p></article><article><div className="portfolio-photo" role="img" aria-label="&#201;tude de packaging minimaliste" style={{ backgroundImage: "url(/media/portfolio/package-v1.webp)" }}/><p>Identit&#233; visuelle <span>&#8594;</span></p></article><article><div className="portfolio-photo" role="img" aria-label="Lumi&#232;re et architecture carib&#233;ennes" style={{ backgroundImage: "url(/media/portfolio/architecture-v1.webp)" }}/><p>Lieux &amp; territoires <span>&#8594;</span></p></article><article><div className="portfolio-photo" role="img" aria-label="Couverture d&#8217;un magazine ind&#233;pendant" style={{ backgroundImage: "url(/media/portfolio/magazine-v1.webp)" }}/><p>&#201;ditions &amp; r&#233;cits <span>&#8594;</span></p></article><article><div className="portfolio-photo" role="img" aria-label="D&#233;tail de textile bleu brod&#233;" style={{ backgroundImage: "url(/media/portfolio/textile-v1.webp)" }}/><p>D&#233;tails <span>&#8594;</span></p></article></section>}
